// a shader variable
let theShader;
let shaderBg;

function preload() {
  // load the shader
  theShader = loadShader("https://openprocessing.org/sketch/1588764/files/shader.vert", "shader.frag");
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);

 // shaders require WEBGL mode to work
  createCanvas(windowWidth, windowHeight);
  noStroke();

  // shaders require WEBGL mode to work
 shaderBg = createGraphics(windowWidth, windowHeight, WEBGL);
}

function draw() {
  // we can draw the background each frame or not.
  // if we do we can use transparency in our shader.
  // if we don't it will leave a trailing after image.
  // background(0);
  // shader() sets the active shader with our shader
   shaderBg.shader(theShader);
	//shader(theShader);

   // get the mouse coordinates, map them to values between 0-1 space
  let yMouse = (map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, height, 0) / height) * 2 - 1;
  let xMouse = ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width) * 2 - 1;

  // Make sure pixels are square
  xMouse = (xMouse * width) / height;
  yMouse = yMouse;

  // pass the interactive information to the shader
  theShader.setUniform("iResolution", [width, height]);
  theShader.setUniform("iTime", millis() / 1000.0);
  theShader.setUniform("iFrame", frameRate());
  theShader.setUniform("iMouse", [xMouse, yMouse]);

  // rect gives us some geometry on the screen to draw the shader on
  // rect gives us some geometry on the screen to draw the shader on
  shaderBg.rect(0, 0, width, height);
  image(shaderBg, 0, 0, width, height);

}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}


// === Tab: shader.frag ===
#ifdef GL_ES
precision highp float;
#endif

uniform vec2 iResolution;
uniform float iTime;
uniform vec2 iMouse;

uniform float iFrame;
varying vec2 vTexCoord;

#define M_PI 3.14159265358979
#define M_E  2.71828182845904

// Convert from Hue,Saturation/Value to RGB
    // http://lolengine.net/blog/2013/07/27/rgb-to-hsv-in-glsl
    vec3 hsv2rgb(vec3 c)
    {
      vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
      vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
      return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
    }

    // https://github.com/d3/d3-color
    vec3 cubehelix(vec3 c) {
      float a = c.y * c.z * (1.0 - c.z);
      float cosh = cos(c.x + M_PI / 2.0);
      float sinh = sin(c.x + M_PI / 2.0);
      return vec3(
        (c.z + a * (1.78277 * sinh - 0.14861 * cosh)),
        (c.z - a * (0.29227 * cosh + 0.90649 * sinh)),
        (c.z + a * (1.97294 * cosh))
      );
    }

    // https://github.com/d3/d3-scale-chromatic
    vec3 cubehelixDefault(float t) {
      return cubehelix(vec3(mix(300.0 / 180.0 * M_PI, -240.0 / 180.0 * M_PI, t), 0.5, t));
    }

    // https://github.com/d3/d3-scale-chromatic
    vec3 cubehelixRainbow(float t) {
      if (t < 0.0 || t > 1.0) t -= floor(t);
      float ts = abs(t - 0.5);
      return cubehelix(vec3((360.0 * t - 100.0) / 180.0 * M_PI, 1.5 - 1.5 * ts, 0.8 - 0.9 * ts));
    }




void main() {

  // copy the vTexCoord
    // vTexCoord is a value that goes from 0.0 - 1.0 depending on the pixels location
    // we can use it to access every pixel on the screen

    vec2 coord = vTexCoord;

    float u = coord.x * 2.0 - 1.0;
    float v = coord.y * 2.0 - 1.0;
    const float scale = 2.0;

    // Make sure pixels are square
    u = u * scale * iResolution.x / iResolution.y + 0.5;
    v = v * scale + 0.5;

    vec2 uv = vec2(u, v);

   // Calculate the to center distance
    float d = length(uv - 0.5) * 2.0;

    // Calculate the ripple time
    float t = d * d * 15.0 - iTime * 33.0;

    // Calculate the ripple thickness
    d = (cos(t) * 0.5 + 0.5) * (1.5 - d);

    // Time varying pixel color
    vec3 col = 0.5 + 0.5 * cos(cubehelixRainbow(t / 40.0) + uv.xyx + vec3(3.0,1.0,1.0));

    // Set the output color to rgb channels and the thickness to alpha channel

    gl_FragColor = vec4(col, d);


}

// === Tab: shader.vert ===
// These are necessary definitions that let you graphics card know how to render the shader
#ifdef GL_ES
precision highp float;
#endif

// our vertex data
attribute vec3 aPosition;

attribute vec2 aTexCoord;

varying vec2 vTexCoord;

void main() {

  vTexCoord = aTexCoord;

  // copy the position data into a vec4, using 1.0 as the w component
  vec4 positionVec4 = vec4(aPosition, 1.0);

  positionVec4.xy = positionVec4.xy * 2.0 - 1.0;

  // send the vertex information on to the fragment shader
  gl_Position = positionVec4;
}

